def seed(apps, schema_editor):
    CrontabSchedule = apps.get_model("django_celery_beat", "CrontabSchedule")
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    for name, task, cron in SCHEDULES:
        crontab, _ = CrontabSchedule.objects.get_or_create(**cron)
        if not PeriodicTask.objects.filter(name=name).exists():
            PeriodicTask.objects.create(name=name, task=task, crontab=crontab, enabled=True)
    CommunicationTemplate = apps.get_model("communication", "CommunicationTemplate")
    for t in TEMPLATES:
        taken = CommunicationTemplate.objects.filter(code=t["code"]) | CommunicationTemplate.objects.filter(name=t["name"])
        if not taken.exists():
            CommunicationTemplate.objects.create(communication_type="email", is_active=True, **t)


